import { icon } from './icons.js';
import { OrbitCalls } from './calls.js';

const $ = (q, root = document) => root.querySelector(q);
setTimeout(()=>document.querySelector('#boot')?.classList.add('done'),6000);
const $$ = (q, root = document) => [...root.querySelectorAll(q)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
const initials = name => name.split(/\s+/).slice(0,2).map(p => p[0]).join('').toUpperCase();
function callSound(kind){try{const ctx=new AudioContext(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.frequency.value={join:660,mute:330,share:880}[kind]||440;gain.gain.setValueAtTime(.05,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.14);osc.connect(gain).connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.15)}catch{}}
const defaultHTML = `<main class="hero">\n  <span class="eyebrow">MINHA PRÓXIMA IDEIA</span>\n  <h1>Olá, mundo<span>.</span></h1>\n  <p>Um espaço em branco é onde tudo começa.</p>\n  <button>Vamos criar</button>\n</main>`;
const defaultCSS = `* { box-sizing: border-box; }\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  background: #f8f4ee;\n  color: #25211f;\n  font-family: system-ui, sans-serif;\n}\n.hero { max-width: 520px; padding: 48px; }\n.eyebrow { color: #a45f39; font-size: 12px; letter-spacing: 2px; }\nh1 { font-size: clamp(48px, 10vw, 84px); margin: 18px 0; }\nh1 span { color: #e78957; }\np { color: #655e59; line-height: 1.7; }\nbutton { margin-top: 20px; padding: 12px 18px; border: 0; border-radius: 8px; background: #25211f; color: white; }`;
const fileInfo={html:{name:'index.html',badge:'<>'},css:{name:'style.css',badge:'#'},javascript:{name:'app.js',badge:'JS'},python:{name:'main.py',badge:'PY'},csharp:{name:'Program.cs',badge:'C#'},cpp:{name:'main.cpp',badge:'C++'},luau:{name:'main.luau',badge:'LU'}};
const fontFamilies={inter:'Inter,system-ui,sans-serif',system:'"Segoe UI",system-ui,sans-serif',serif:'Georgia,"Times New Roman",serif',mono:'Consolas,"Courier New",monospace',rounded:'"Trebuchet MS","Segoe UI",sans-serif'};
const fontOptions=(selected='inter',inherit=false)=>`${inherit?'<option value="inherit">Herdar do servidor</option>':''}${Object.entries({inter:'Inter limpa',system:'Segoe UI',serif:'Georgia elegante',mono:'Consolas técnica',rounded:'Trebuchet arredondada'}).map(([value,label])=>`<option value="${value}" ${value===selected?'selected':''}>${label}</option>`).join('')}`;
const emptyCode={html:defaultHTML,css:defaultCSS,javascript:'// JavaScript do projeto\n',python:'# Python\n',csharp:'// C#\n',cpp:'// C++\n',luau:'-- Luau\n'};
const state = { data:null, serverId:'orbit', channelId:'geral', dmUserId:null, replyTo:null, view:'chat', file:'html', code:{...emptyCode}, codeChannel:null, messages:new Map(), clientId:crypto.randomUUID(), csrf:'', aiHistory:[], aiSnippets:new Map(), includeCode:false, typing:new Map(), events:null, saveTimer:null, validateTimer:null };
const credentialsKey='codestate-credentials-v1';
function savedCredentials(){try{const value=JSON.parse(localStorage.getItem(credentialsKey));return value?.username&&value?.password?value:null}catch{return null}}
function saveCredentials(value){localStorage.setItem(credentialsKey,JSON.stringify({username:value.username,password:value.password,name:value.name||value.username}))}
function forgetCredentials(){localStorage.removeItem(credentialsKey)}

function hydrateIcons(root=document) { $$('[data-icon]', root).forEach(el => { if (!el.dataset.hydrated) { el.insertAdjacentHTML('afterbegin', icon(el.dataset.icon)); el.dataset.hydrated='1'; } }); }
async function api(path, options={}) {
  const init={method:options.method||'GET',headers:{},credentials:'same-origin'};
  if (options.body !== undefined) { init.headers['Content-Type']='application/json'; init.headers['X-Orbit-Request']='1'; if (state.csrf) init.headers['X-CSRF-Token']=state.csrf; init.body=JSON.stringify(options.body); }
  const res=await fetch(path,init); let data={}; try{data=await res.json();}catch{}
  if (!res.ok) throw new Error(data.error||'Não foi possível concluir esta ação.'); return data;
}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='toast'+(error?' error':'');el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,3800)}
function modal(html){const d=$('#modal');$('#modal-content').innerHTML=html;hydrateIcons(d);if(!d.open)d.showModal()}
function closeModal(){const d=$('#modal');if(d.open)d.close()}
function formatTime(ts){return new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(ts)}
function avatarHTML(user,online=false){return `<span class="avatar ${user.color}">${user.avatar?`<img src="${esc(user.avatar)}" alt="">`:esc(initials(user.name))}${online?'<i class="online-dot"></i>':''}</span>`}
function activeServer(){return state.data.servers.find(s=>s.id===state.serverId)||state.data.servers[0]}
function activeChannel(){return state.data.channels.find(c=>c.id===state.channelId)}

async function boot(){
  hydrateIcons();
  let created;
  try { state.data=await api('/api/bootstrap'); }
  catch {
    const saved=savedCredentials();
    if(saved)try{await api('/api/login',{method:'POST',body:saved});state.data=await api('/api/bootstrap')}catch{try{await api('/api/recover',{method:'POST',body:{...saved,terms:true}});state.data=await api('/api/bootstrap')}catch{forgetCredentials()}}
    if(!state.data){created=await captchaGate();if(created?.credentials)saveCredentials(created.credentials);state.data=await api('/api/bootstrap')}
  }
  state.csrf=state.data.csrf;if(state.data.user.guest){created=await api('/api/auto-account',{method:'POST',body:{}});if(created.credentials)saveCredentials({...created.credentials,name:state.data.user.name});state.data=await api('/api/bootstrap');state.csrf=state.data.csrf}state.serverId=state.data.servers[0]?.id||'orbit';state.aiHistory=state.data.aiHistory||[];const remembered=savedCredentials();if(remembered&&remembered.username===state.data.user.username)saveCredentials({...remembered,name:state.data.user.name});
  const first=state.data.channels.find(c=>c.server_id===state.serverId&&c.type==='text'); state.channelId=first?.id;
  if(state.data.project) state.code={...emptyCode,...state.data.project}; else { const local=localStorage.getItem('orbit-project'); if(local)try{state.code={...state.code,...JSON.parse(local)}}catch{} }
  renderShell(); connectEvents(); await openChannel(state.channelId); updateEditor(); renderMembers(); renderAIState();renderAIHistory();
  api('/api/ai/providers').then(result=>{state.data.aiProviders=result.providers;renderAIState()}).catch(()=>{});
  setTimeout(()=>$('#boot').classList.add('done'),Math.max(0,850-performance.now()));
  if(created?.credentials)setTimeout(()=>showCredentials(created.credentials,true),220);
}
async function captchaGate(){return new Promise(async(resolve,reject)=>{let challenge;const login=()=>{modal(`${modalHeader('Entrar na sua conta')}<p class="modal-description">Use as credenciais geradas pelo CodeState em outro dispositivo.</p><form id="login-form" class="modal-form"><label class="field">Usuário<input name="username" minlength="3" maxlength="32" autocomplete="username" required></label><label class="field">Senha<input name="password" type="password" minlength="10" maxlength="128" autocomplete="current-password" required></label><div class="form-error"></div><div class="form-actions"><button type="button" class="text-button" id="login-back">Voltar</button><button class="primary-button">Entrar</button></div></form>`);wireClose();$('#login-back').onclick=load;$('#login-form').onsubmit=async e=>{e.preventDefault();try{const credentials={username:e.target.username.value.trim(),password:e.target.password.value};await api('/api/login',{method:'POST',body:credentials});saveCredentials(credentials);closeModal();resolve({login:true})}catch(error){$('.form-error',$('#modal')).textContent=error.message}}};const load=async()=>{challenge=await api('/api/captcha');modal(`<div class="captcha-gate"><div class="cs-mark">CS</div><h2>Confirme que é você</h2><p>Digite os caracteres mostrados na imagem. O CodeState criará e salvará uma conta segura para você.</p><img src="${challenge.image}" alt="Código de acesso"><form id="captcha-form"><input name="answer" minlength="6" maxlength="6" autocomplete="off" autofocus required placeholder="Código da imagem"><label class="terms-check"><input name="terms" type="checkbox" required><span>Li e aceito os <a href="/terms.html" target="_blank" rel="noopener">Termos e Regras</a>.</span></label><button class="primary-button">Entrar</button></form><div class="form-error"></div><div class="captcha-actions"><button class="text-button" id="existing-account">Já tenho uma conta</button><button class="text-button" id="new-captcha">Gerar outra imagem</button></div></div>`);$('#captcha-form').onsubmit=async e=>{e.preventDefault();try{const created=await api('/api/guest',{method:'POST',body:{captchaId:challenge.id,captchaText:e.target.answer.value,terms:e.target.terms.checked}});closeModal();resolve(created)}catch(error){$('.form-error',$('#modal')).textContent=error.message;challenge=await api('/api/captcha');$('.captcha-gate img').src=challenge.image;e.target.answer.value='';e.target.answer.focus()}};$('#existing-account').onclick=login;$('#new-captcha').onclick=load};try{await load()}catch(error){reject(error)}})}
function renderShell(){
  const user=state.data.user; $('#my-avatar').innerHTML=user.avatar?`<img src="${esc(user.avatar)}" alt="">`:esc(initials(user.name));$('#my-avatar').className=`avatar ${user.color}`;$('#my-name').textContent=user.name;$('#my-status').textContent=user.guest?'Conta de visitante':'Pronto para criar';$('.profile-bar').style.backgroundImage=user.banner?`linear-gradient(90deg,#080808e8,#080808b8),url("${user.banner}")`:'';
  $('#server-list').innerHTML=state.data.servers.map(s=>`<button class="server-button ${s.id===state.serverId?'active':''}" data-server="${esc(s.id)}" aria-label="${esc(s.name)}" title="${esc(s.name)}">${s.icon?`<img src="${esc(s.icon)}" alt="">`:esc(initials(s.name))}</button>`).join('');
  const server=activeServer();$('#workspace-name').textContent=server.name;$('#breadcrumb-server').textContent=server.name;document.documentElement.style.setProperty('--server-font',fontFamilies[server.font]||fontFamilies.inter);$('.workspace').style.backgroundImage=server.icon?`linear-gradient(90deg,#0b0b0bf2,#0b0b0bcc),url("${server.icon}")`:'';$('#manage-roles').hidden=server.ownerId!==user.id&&!server.permissions?.includes('administrator')&&!server.permissions?.includes('manage_roles');
  const channels=state.data.channels.filter(c=>c.server_id===server.id);
  $('#text-channels').innerHTML=channels.filter(c=>c.type==='text').map(c=>channelHTML(c)).join('');
  $('#code-channels').innerHTML=channels.filter(c=>c.type==='code').map(c=>channelHTML(c)).join('');
  $('#voice-channels').innerHTML=channels.filter(c=>c.type==='voice').map(c=>channelHTML(c)).join('');
  renderDirects();
  hydrateIcons();
}
function renderDirects(){const friends=state.data.friends||[],requests=state.data.friendRequests||[];$('#direct-chats').innerHTML=friends.map(user=>`<button class="direct-user ${state.dmUserId===user.id?'active':''}" data-direct="${esc(user.id)}">${avatarHTML(user,user.online)}<span>${esc(user.name)}</span></button>`).join('');$('#friend-requests').innerHTML=requests.map(user=>`<div class="friend-request"><span><strong>${esc(user.name)}</strong><small>@${esc(user.username)}</small></span><div><button class="icon-button" data-friend-accept="${esc(user.id)}" title="Aceitar" data-icon="check"></button><button class="icon-button" data-friend-reject="${esc(user.id)}" title="Recusar" data-icon="close"></button></div></div>`).join('');hydrateIcons($('#friend-requests'));hydrateIcons($('#direct-chats'))}
function channelHTML(c){const count=state.data.calls?.[c.id]||0,family=c.font&&c.font!=='inherit'?fontFamilies[c.font]:null;return `<button class="channel-button ${c.vfx?'channel-vfx':''} ${c.id===state.channelId&&((c.type==='code'&&state.view==='editor')||(c.type==='text'&&state.view==='chat'))?'active':''} ${calls.channel?.id===c.id?'in-call':''}" style="${family?`font-family:${family}`:''}" data-channel="${esc(c.id)}" data-type="${c.type}"><span data-icon="${c.type==='text'?'hash':c.type==='code'?'code':'volume'}"></span><span class="channel-name">${esc(c.name)}</span>${count?`<span class="channel-badge">${count}</span>`:''}</button>`}
async function refresh(){const fresh=await api('/api/bootstrap');state.data={...fresh};state.csrf=fresh.csrf;if(!fresh.servers.some(s=>s.id===state.serverId))state.serverId=fresh.servers[0]?.id;renderShell();renderMembers()}
async function openChannel(id){const c=state.data.channels.find(x=>x.id===id);if(!c)return;if(c.type==='voice')return joinCall(c,false);if(c.type==='code')return openCodeChannel(c);state.codeChannel=null;state.dmUserId=null;clearReply();state.channelId=id;state.view='chat';showView('chat');renderShell();$('#channel-name').textContent=c.name;$('#channel-description').textContent=c.description;$('#message-input').placeholder=`Converse em #${c.name}`;$('#channel-icon').innerHTML=icon('hash');$('#composer-wrap').hidden=Boolean(c.read_only);$('#read-only-notice').hidden=!c.read_only;await loadMessages();closeMobileMenu()}
async function openCodeChannel(c){state.dmUserId=null;clearReply();const data=await api(`/api/code-channel?channelId=${encodeURIComponent(c.id)}`);state.channelId=c.id;state.codeChannel={...data,channel:c};state.code={...emptyCode,...data.files};state.file=Object.keys(data.files)[0]||'html';showView('editor');updateEditor();$('#channel-name').textContent=c.name;$('#channel-description').textContent='Canal de código · alterações passam pela aprovação do dono';$('#channel-icon').innerHTML=icon('code');closeMobileMenu()}
async function openDirect(userId){const user=(state.data.friends||[]).find(friend=>friend.id===userId);if(!user)return;state.dmUserId=user.id;state.channelId=null;state.codeChannel=null;clearReply();showView('chat');renderShell();$('#channel-name').textContent=user.name;$('#channel-description').textContent=`Conversa privada com @${user.username}`;$('#channel-icon').innerHTML=icon('messageCircle');$('#message-input').placeholder=`Mensagem para ${user.name}`;$('#composer-wrap').hidden=false;$('#read-only-notice').hidden=true;const key=`dm:${user.id}`,list=await api(`/api/direct-messages?userId=${encodeURIComponent(user.id)}`);state.messages.set(key,list);renderMessages();requestAnimationFrame(()=>{$('#conversation-scroll').scrollTop=$('#conversation-scroll').scrollHeight});closeMobileMenu()}
function showView(view){state.view=view;$('#chat-view').hidden=view!=='chat';$('#editor-view').hidden=view!=='editor';$('#call-view').hidden=view!=='call';$('#playground-nav').classList.toggle('active',view==='editor'&&!state.codeChannel);if(view==='editor'&&!state.codeChannel){$('#channel-name').textContent='Playground';$('#channel-description').textContent='HTML, CSS, JS, Python, C#, C++ e Luau.';$('#channel-icon').innerHTML=icon('code')}renderShell()}
async function loadMessages(){const list=await api(`/api/messages?channelId=${encodeURIComponent(state.channelId)}`);state.messages.set(state.channelId,list);renderMessages();requestAnimationFrame(()=>{$('#conversation-scroll').scrollTop=$('#conversation-scroll').scrollHeight})}
function currentMessageKey(){return state.dmUserId?`dm:${state.dmUserId}`:state.channelId}
function renderMessages(){const list=state.messages.get(currentMessageKey())||[];$('#welcome-banner').hidden=Boolean(state.dmUserId)||state.serverId!=='orbit'||state.channelId!=='geral';$('#quick-links').hidden=$('#welcome-banner').hidden;$('#empty-chat').hidden=list.length>0;$('#message-count').textContent=list.length?`${list.length} mensagens`:'';$('#messages').innerHTML=list.map(messageHTML).join('');hydrateIcons($('#messages'))}
function rich(text){return esc(text).replace(/```([\s\S]*?)```/g,'<pre><code>$1</code></pre>').replace(/`([^`\n]+)`/g,'<code>$1</code>').replace(/\n/g,'<br>')}
const fileSize=size=>size>=1048576?`${(size/1048576).toFixed(1)} MB`:`${Math.max(1,Math.round(size/1024))} KB`;
function attachmentHTML(file){const url=esc(file.url),name=esc(file.name);if(/^image\/(png|jpeg|webp|gif)$/i.test(file.mime))return `<div class="attachment-image"><img src="${url}" alt="${name}" loading="lazy"><span>${name} · ${fileSize(file.size)}</span></div>`;if(/^video\/(mp4|webm)$/i.test(file.mime))return `<div class="attachment-media"><video src="${url}" controls preload="metadata"></video><span>${name} · ${fileSize(file.size)}</span></div>`;if(/^audio\/(mpeg|ogg|wav|webm)$/i.test(file.mime))return `<div class="attachment-media"><audio src="${url}" controls preload="metadata"></audio><span>${name} · ${fileSize(file.size)}</span></div>`;return `<a class="attachment-file" href="${url}" download>${icon('file',20)}<span><strong>${name}</strong><small>${fileSize(file.size)}</small></span>${icon('download',16)}</a>`}
function messageHTML(m){const own=m.user.id===state.data.user.id,readOnly=Boolean(activeChannel()?.read_only),attachments=(m.attachments||[]).map(attachmentHTML).join(''),groups=Object.entries((m.reactions||[]).reduce((a,r)=>{(a[r.emoji]??=[]).push(r.userId);return a},{})),reference=m.reply?`<div class="message-reference">${icon('reply',11)}<strong>${esc(m.reply.user.name)}</strong><span>${esc(m.reply.content.slice(0,160))}</span></div>`:'',forwarded=m.forwardedAuthor?`<div class="forwarded-label">${icon('forward',11)} Encaminhada de ${esc(m.forwardedAuthor)}</div>`:'';return `<article class="message" id="msg-${m.id}">${avatarHTML(m.user)}<div class="message-content"><div class="message-meta"><strong>${esc(m.user.name)}</strong>${m.user.id==='orbit-guide'?'<span class="bot-badge">CODESTATE</span>':''}<time datetime="${new Date(m.createdAt).toISOString()}">hoje, ${formatTime(m.createdAt)}</time></div>${forwarded}${reference}<div class="message-text">${rich(m.content)}</div>${attachments?`<div class="attachments">${attachments}</div>`:''}${groups.length?`<div class="reactions">${groups.map(([e,ids])=>`<button class="reaction ${ids.includes(state.data.user.id)?'selected':''}" data-react="${e}" data-message="${m.id}" ${readOnly?'disabled':''}>${e}<span>${ids.length}</span></button>`).join('')}</div>`:''}</div>${readOnly?'':`<div class="message-actions"><button class="icon-button" data-reply="${m.id}" title="Responder" data-icon="reply"></button><button class="icon-button" data-forward="${m.id}" title="Encaminhar" data-icon="forward"></button>${m.direct?'':`<button class="icon-button" data-react="✨" data-message="${m.id}" title="Reagir" data-icon="sparkles"></button>`}${own&&!m.direct?`<button class="icon-button" data-delete="${m.id}" title="Excluir" data-icon="trash"></button>`:''}</div>`}</article>`}
function addMessage(m){const list=state.messages.get(m.channelId)||[];if(!list.some(x=>x.id===m.id))list.push(m);state.messages.set(m.channelId,list);if(m.channelId===state.channelId){calls.channel?.id===m.channelId?renderCallMessages():renderMessages();requestAnimationFrame(()=>{$('#conversation-scroll').scrollTop=$('#conversation-scroll').scrollHeight})}}
function addDirectMessage(m){const list=state.messages.get(m.channelId)||[];if(!list.some(item=>item.id===m.id))list.push(m);state.messages.set(m.channelId,list);if(state.dmUserId===m.peerId){renderMessages();requestAnimationFrame(()=>{$('#conversation-scroll').scrollTop=$('#conversation-scroll').scrollHeight})}}
function clearReply(){state.replyTo=null;const bar=$('#reply-bar');if(bar){bar.hidden=true;$('span',bar).textContent=''}}
function setReply(messageId){const message=(state.messages.get(currentMessageKey())||[]).find(item=>item.id===messageId);if(!message)return;state.replyTo=message;const bar=$('#reply-bar');$('span',bar).textContent=`Respondendo a ${message.user.name}: ${message.content.slice(0,90)}`;bar.hidden=false;$('#message-input').focus()}
function connectEvents(){
  state.events?.close(); const es=new EventSource(`/api/events?clientId=${state.clientId}`);state.events=es;
  es.addEventListener('connected',()=>{$('#connection-status').innerHTML='<i class="status-dot"></i> Ao vivo'});
  es.addEventListener('message',e=>addMessage(JSON.parse(e.data)));
  es.addEventListener('direct-message',e=>addDirectMessage(JSON.parse(e.data)));
  es.addEventListener('friends-refresh',()=>refresh().catch(showError));
  es.addEventListener('message-updated',e=>{const m=JSON.parse(e.data),list=state.messages.get(m.channelId)||[],i=list.findIndex(x=>x.id===m.id);if(i>=0)list[i]=m;if(m.channelId===state.channelId)renderMessages()});
  es.addEventListener('message-deleted',e=>{const d=JSON.parse(e.data),list=state.messages.get(d.channelId)||[];state.messages.set(d.channelId,list.filter(x=>x.id!==d.id));if(d.channelId===state.channelId)renderMessages()});
  es.addEventListener('presence',e=>{const d=JSON.parse(e.data);if(d.serverId===state.serverId){const online=new Map(d.users.map(u=>[u.id,u]));state.data.members=state.data.members.map(m=>m.serverId===d.serverId?{...m,...(online.get(m.id)||{}),online:online.has(m.id)}:m);renderMembers()}});
  es.addEventListener('typing',e=>{const d=JSON.parse(e.data);if(d.channelId===state.channelId&&d.user.id!==state.data.user.id){state.typing.set(d.user.id,{name:d.user.name,expires:Date.now()+2500});renderTyping();setTimeout(renderTyping,2600)}});
  es.addEventListener('code-proposal',e=>{const d=JSON.parse(e.data);if(state.codeChannel?.channel.id===d.channelId)openCodeChannel(state.codeChannel.channel).catch(showError)});
  es.addEventListener('refresh',()=>refresh().catch(showError));es.addEventListener('calls',e=>{state.data.calls=JSON.parse(e.data);renderShell()});
  es.addEventListener('signal',e=>calls.signal(JSON.parse(e.data)));es.addEventListener('peer-left',e=>calls.dropPeer(JSON.parse(e.data).clientId));es.addEventListener('screen-frame',e=>calls.receiveScreenFrame(JSON.parse(e.data)));es.addEventListener('screen-stopped',e=>calls.receiveScreenStopped(JSON.parse(e.data)));
  es.addEventListener('session-expired',()=>location.reload());es.onerror=()=>{$('#connection-status').innerHTML='<i class="status-dot" style="background:#d97868"></i> Reconectando'};
}
function renderTyping(){const now=Date.now();for(const[k,v]of state.typing)if(v.expires<now)state.typing.delete(k);const names=[...state.typing.values()].map(v=>v.name);$('#typing-line').textContent=names.length?`${names.slice(0,2).join(' e ')} está digitando…`:''}

function renderRemoteScreenFrame(peerId,frame){const tile=$(`[data-peer="${peerId}"]`);if(!tile)return;let image=$('.screen-fallback',tile);if(!image){image=document.createElement('img');image.className='screen-fallback';image.alt='Tela compartilhada';tile.append(image)}image.src=frame;image.hidden=false}
function hideRemoteScreenFrame(peerId){const image=$(`[data-peer="${peerId}"] .screen-fallback`);if(image){image.hidden=true;image.removeAttribute('src')}}
const calls=new OrbitCalls({api,clientId:state.clientId,onChange:renderCall,onFrame:renderRemoteScreenFrame,onScreenStopped:hideRemoteScreenFrame,onError:showError});
async function joinCall(c,video){try{await calls.join(c,state.data.user,video);callSound('join');state.channelId=c.id;showView('call');$('#channel-name').textContent=c.name;$('#channel-description').textContent='Chamada protegida por WebRTC';$('#channel-icon').innerHTML=icon('volume');state.messages.set(c.id,await api(`/api/messages?channelId=${encodeURIComponent(c.id)}`));renderCall();closeMobileMenu()}catch(e){showError(e)}}
function renderCall(){
  const mini=$('#call-mini');mini.hidden=!calls.channel; if(calls.channel)mini.innerHTML=`<div><button class="return-call" data-action="return-call">${icon('volume',15)} ${esc(calls.channel.name)}</button><button class="icon-button" data-action="leave-call">${icon('phoneOff',15)}</button></div><small>${calls.peers.size+1} participante${calls.peers.size?'s':''} · conectado</small>`;
  if(!calls.channel)return;$('#call-title').textContent=calls.channel.name;const items=[{id:'local',user:state.data.user,stream:calls.localStream,local:true},...[...calls.peers].map(([id,p])=>({id,user:p.user,stream:p.stream,fallbackFrame:p.fallbackFrame,fallbackVisible:p.fallbackVisible}))];
  $('#call-grid').innerHTML=items.map(x=>`<div class="video-tile" data-peer="${x.id}">${avatarHTML(x.user)}<video ${x.local?'muted':''} autoplay playsinline class="${x.local&&!calls.screen?'local-camera':''}"></video>${!x.local&&x.fallbackVisible&&x.fallbackFrame?`<img class="screen-fallback" src="${esc(x.fallbackFrame)}" alt="Tela compartilhada">`:''}<span class="video-name">${icon(x.local&& !calls.mic?'micOff':'mic',11)} ${esc(x.user.name)}${x.local?' (você)':''}</span></div>`).join('');
  items.forEach(x=>{const tile=$(`[data-peer="${x.id}"]`),v=$('video',tile);if(v&&x.stream){v.srcObject=x.stream;v.play().catch(()=>{})}});
  const mic=$('[data-action="toggle-mic"]');mic.innerHTML=icon(calls.mic?'mic':'micOff');mic.classList.toggle('off',!calls.mic);const cam=$('[data-action="toggle-camera"]');cam.innerHTML=icon(calls.camera?'video':'videoOff');cam.classList.toggle('off',!calls.camera);$('[data-action="share-screen"]').classList.toggle('active',calls.screen);renderShell();
  renderCallMessages();
}
function renderCallMessages(){const box=$('#call-messages');if(!box)return;box.innerHTML=(state.messages.get(state.channelId)||[]).map(m=>`<article><strong>${esc(m.user.name)}</strong><p>${rich(m.content)}</p>${(m.attachments||[]).map(attachmentHTML).join('')}</article>`).join('');box.scrollTop=box.scrollHeight}

function updateEditor(){const input=$('#code-input'),info=fileInfo[state.file];$('#file-tabs').innerHTML=Object.entries(fileInfo).map(([key,item])=>`<button class="file-tab ${key===state.file?'active':''}" data-file="${key}"><span class="file-type">${esc(item.badge)}</span>${esc(item.name)}</button>`).join('');input.value=state.code[state.file]||'';input.setAttribute('aria-label',`Editor de código ${info.name}`);$('[data-action="submit-proposal"]').hidden=!state.codeChannel;$('[data-action="review-proposals"]').hidden=!state.codeChannel?.owner;$('#diagnostics').hidden=true;lineNumbers();preview();hydrateIcons($('#editor-view'))}
function lineNumbers(){const input=$('#code-input');$('#line-numbers').textContent=Array.from({length:input.value.split('\n').length},(_,i)=>i+1).join('\n')}
function nativePreview(language,code){
  let title='Minha interface',widgets=[];const push=(type,text='')=>widgets.push({type,text:text||({button:'Botão',input:'Digite aqui',check:'Opção'}[type]||'Texto')});
  const titlePatterns={python:/\.title\(\s*["']([^"']+)/,csharp:/(?:this\.)?Text\s*=\s*"([^"]+)"/,cpp:/setWindowTitle\(\s*"([^"]+)"/,luau:/(?:Name|Title)\s*=\s*["']([^"']+)/};title=code.match(titlePatterns[language])?.[1]||title;
  if(language==='python'){for(const match of code.matchAll(/(?:ttk\.)?(Label|Button|Entry|Checkbutton|Radiobutton)\s*\(([^)]*)\)/gi)){const kind=match[1].toLowerCase(),text=match[2].match(/text\s*=\s*["']([^"']*)/)?.[1];push(kind==='button'?'button':kind==='entry'?'input':kind.includes('check')||kind.includes('radio')?'check':'label',text)}for(const match of code.matchAll(/Q(Label|PushButton|LineEdit|CheckBox|RadioButton)\s*\(\s*(?:["']([^"']*)["'])?/gi)){const kind=match[1].toLowerCase();push(kind==='pushbutton'?'button':kind==='lineedit'?'input':kind.includes('check')||kind.includes('radio')?'check':'label',match[2])}}
  if(language==='csharp'){for(const match of code.matchAll(/new\s+(Label|Button|TextBox|CheckBox|RadioButton)[\s\S]{0,180}?Text\s*=\s*"([^"]*)"/gi)){const kind=match[1].toLowerCase();push(kind==='button'?'button':kind==='textbox'?'input':kind.includes('check')||kind.includes('radio')?'check':'label',match[2])}}
  if(language==='cpp'){for(const match of code.matchAll(/(?:new\s+)?Q(Label|PushButton|LineEdit|CheckBox|RadioButton)\s*\(\s*(?:"([^"]*)")?/gi)){const kind=match[1].toLowerCase();push(kind==='pushbutton'?'button':kind==='lineedit'?'input':kind.includes('check')||kind.includes('radio')?'check':'label',match[2])}for(const match of code.matchAll(/ImGui::(Text|Button|InputText|Checkbox|RadioButton)\s*\(\s*"([^"]*)"/gi)){const kind=match[1].toLowerCase();push(kind==='button'?'button':kind==='inputtext'?'input':kind.includes('check')||kind.includes('radio')?'check':'label',match[2])}}
  if(language==='luau'){for(const match of code.matchAll(/\.(Text|PlaceholderText)\s*=\s*["']([^"']*)/gi))push(match[1].toLowerCase().includes('placeholder')?'input':/button/i.test(code.slice(Math.max(0,match.index-120),match.index))?'button':'label',match[2])}
  const controls=widgets.slice(0,16).map(w=>w.type==='button'?`<button>${esc(w.text)}</button>`:w.type==='input'?`<input placeholder="${esc(w.text)}">`:w.type==='check'?`<label class="check"><input type="checkbox"> ${esc(w.text)}</label>`:`<p>${esc(w.text)}</p>`).join('');
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#0b0b0c;color:#f4f4f4;font-family:system-ui;display:grid;place-items:center;padding:28px}.window{width:min(560px,100%);border:1px solid #3d3d42;border-radius:14px;background:#171719;box-shadow:0 24px 70px #0008;overflow:hidden}.title{padding:11px 15px;border-bottom:1px solid #333;font-size:12px}.content{padding:24px;display:grid;gap:12px}.note{color:#8d8d94;font-size:10px;margin:0 0 4px}.content>p{font-size:14px;margin:0}.content>button,.content>input{border:1px solid #444;border-radius:8px;padding:11px 13px;background:#f4f4f4;color:#111}.content>input{background:#0d0d0e;color:#fff}.check{font-size:12px;color:#ccc}</style></head><body><section class="window"><header class="title">${esc(title)} · ${esc(fileInfo[language].name)}</header><div class="content"><p class="note">PRÉVIA ESTRUTURAL AO VIVO</p>${controls||'<p>Nenhum controle de UI reconhecido ainda.</p><p class="note">Use Tkinter/ttk, WinForms, Qt ou propriedades Text do Luau.</p>'}</div></section></body></html>`;
}
function preview(){const web=['html','css','javascript'].includes(state.file);$('#preview-label').textContent=web?'PRÉVIA WEB AO VIVO':'PRÉVIA DE UI AO VIVO';$('#preview-file').textContent=fileInfo[state.file].name;if(!web){$('#preview').srcdoc=nativePreview(state.file,state.code[state.file]||'');return}const safeStyle=(state.code.css||'').replace(/<\/style/gi,'<\\/style'),safeScript=(state.code.javascript||'').replace(/<\/script/gi,'<\\/script');$('#preview').srcdoc=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><style>${safeStyle}</style></head><body>${state.code.html||''}<script>${safeScript}<\/script></body></html>`}
async function validateCode(silent=false){const panel=$('#diagnostics');if(!silent){panel.hidden=false;panel.className='diagnostics';panel.textContent='Analisando…'}try{const result=await api('/api/validate',{method:'POST',body:{language:state.file,code:state.code[state.file]||''}});panel.hidden=false;panel.className=`diagnostics ${result.valid?'valid':'invalid'}`;panel.textContent=`${result.valid?'✓ Sintaxe válida':'✕ Erro de sintaxe'} · ${result.engine}${result.available===false?' (verificação estrutural)':''}\n${result.output||''}`}catch(error){if(!silent)showError(error)}}
function saveLocal(){localStorage.setItem('orbit-project',JSON.stringify(state.code));$('#save-status').textContent='Salvo neste navegador'}
async function saveProject(){try{await api('/api/project',{method:'PUT',body:{files:state.code}});$('#save-status').textContent='Salvo na sua conta';toast('Projeto salvo.')}catch(e){showError(e)}}
async function uploadFiles(files){const list=[...files].slice(0,10);for(let i=0;i<list.length;i++){const file=list[i],path=state.dmUserId?`/api/direct-files?userId=${encodeURIComponent(state.dmUserId)}`:`/api/files?channelId=${encodeURIComponent(state.channelId)}`;$('#connection-status').textContent=`Enviando ${i+1}/${list.length}…`;const response=await fetch(path,{method:'POST',credentials:'same-origin',headers:{'Content-Type':file.type||'application/octet-stream','X-Orbit-Request':'1','X-CSRF-Token':state.csrf,'X-File-Name':encodeURIComponent(file.name)},body:file});let result={};try{result=await response.json()}catch{}if(!response.ok)throw new Error(result.error||`Falha ao enviar ${file.name}.`);state.dmUserId?addDirectMessage(result):addMessage(result)}$('#connection-status').innerHTML='<i class="status-dot"></i> Ao vivo';toast(`${list.length} arquivo${list.length===1?'':'s'} enviado${list.length===1?'':'s'}.`)}
function renderMembers(){if(!state.data)return;const members=state.data.members.filter(m=>m.serverId===state.serverId),online=members.filter(m=>m.online||m.bot),offline=members.filter(m=>!m.online&&!m.bot);$('#members-list').innerHTML=memberGroup('ONLINE',online)+memberGroup('OFFLINE',offline);hydrateIcons($('#members-list'))}
function memberGroup(label,users){if(!users.length)return'';const friends=new Set((state.data.friends||[]).map(friend=>friend.id)),sent=new Set(state.data.sentRequests||[]);return `<h3 class="member-section-title">${label} — ${users.length}</h3>${users.map(u=>`<div class="member-row">${avatarHTML(u,u.online)}<span><strong>${esc(u.name)} ${u.bot?'<span class="bot-badge">CODESTATE</span>':''}</strong><small>${u.bot?'Seu guia criativo':u.online?'Criando agora':'Ausente'}</small>${u.roles?.length?`<span class="member-roles">${u.roles.map(role=>`<i style="--role:${role.color}">${esc(role.name)}</i>`).join('')}</span>`:''}</span>${!u.bot&&u.id!==state.data.user.id?friends.has(u.id)?`<button class="icon-button member-contact" data-direct="${esc(u.id)}" title="Mensagem privada" data-icon="messageCircle"></button>`:`<button class="icon-button member-contact" data-add-username="${esc(u.username)}" title="${sent.has(u.id)?'Pedido enviado':'Adicionar pessoa'}" data-icon="userPlus" ${sent.has(u.id)?'disabled':''}></button>`:''}</div>`).join('')}`}
function showRight(panel='ai'){$('#right-panel').classList.add('open');$$('.right-tab').forEach(b=>b.classList.toggle('active',b.dataset.panel===panel));$('#ai-panel').hidden=panel!=='ai';$('#members-panel').hidden=panel!=='members';if(panel==='ai')setTimeout(()=>$('#ai-input').focus(),150)}
function renderAIState(){const select=$('#ai-model'),providers=state.data.aiProviders||[{id:'demo',name:'Demonstração',available:true}];select.innerHTML=providers.map(p=>`<option value="${p.id}" ${p.available?'':'disabled'}>${esc(p.name)}${p.available?'':' · configure'}</option>`).join('');const preferred=localStorage.getItem('orbit-ai-provider');select.value=providers.some(p=>p.id===preferred&&p.available)?preferred:'demo';$('#ai-disclaimer').textContent=select.value==='demo'?'IA Beta demonstrativa: respostas simples, aguarde a conclusão.':'IA Beta gratuita: pode demorar e cometer erros. Aguarde a resposta completa.'}
function addAIBubble(role,text,demo=false){$('#ai-welcome').hidden=true;const div=document.createElement('div');div.className=`ai-bubble ${role}`;if(role==='assistant')div.innerHTML=`<div class="ai-answer-meta">${icon('sparkles',14)} CodeState AI ${demo?'<small>DEMO</small>':''}</div><div class="ai-answer-body"></div>`;else div.textContent=text;$('#ai-messages').append(div);$('#ai-scroll').scrollTop=$('#ai-scroll').scrollHeight;return div}
function structuredAI(text){let cursor=0,html='',match;const pattern=/```([\w+#-]+)?\s*\n?([\s\S]*?)```/gi;while((match=pattern.exec(text))){html+=rich(text.slice(cursor,match.index));let language=(match[1]||'code').toLowerCase();language=({js:'javascript',py:'python',cs:'csharp','c#':'csharp',cxx:'cpp','c++':'cpp',lua:'luau'}[language]||language);const code=match[2].trim(),id=crypto.randomUUID();state.aiSnippets.set(id,{language,code});const applicable=fileInfo[language];html+=`<details class="ai-code-card" ${code.length<1800?'open':''}><summary><span>${icon('code',13)} ${esc(language.toUpperCase())} · ${code.split('\n').length} linhas</span><span>Expandir ${icon('chevron',12)}</span></summary><pre><code contenteditable="true" spellcheck="false" data-edit-code="${id}">${esc(code)}</code></pre>${applicable?`<button class="apply-code" data-apply-code="${id}">${icon('sparkles',13)} Aplicar em ${esc(applicable.name)} e atualizar a prévia</button>`:''}</details>`;cursor=pattern.lastIndex}const prose=html+rich(text.slice(cursor));return text.length>1800?`<details class="ai-long-answer"><summary>Resposta completa · ${text.length} caracteres</summary><div>${prose}</div></details>`:prose}
function renderAIHistory(){if(!state.aiHistory.length)return;$('#ai-messages').innerHTML='';for(const message of state.aiHistory){const bubble=addAIBubble(message.role,message.content);if(message.role==='assistant')$('.ai-answer-body',bubble).innerHTML=structuredAI(message.content)}hydrateIcons($('#ai-messages'));$$('[data-edit-code]',$('#ai-messages')).forEach(el=>el.addEventListener('input',()=>{const snippet=state.aiSnippets.get(el.dataset.editCode);if(snippet)snippet.code=el.textContent}))}
async function typeAIAnswer(text,demo=false){const div=addAIBubble('assistant','',demo),body=$('.ai-answer-body',div),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;body.classList.add('typing-cursor');if(reduced){body.textContent=text}else{for(const letter of text){body.textContent+=letter;$('#ai-scroll').scrollTop=$('#ai-scroll').scrollHeight;await new Promise(r=>setTimeout(r,9))}}body.classList.remove('typing-cursor');body.innerHTML=structuredAI(text);hydrateIcons(body);$('#ai-scroll').scrollTop=$('#ai-scroll').scrollHeight}
async function askAI(prompt){if(!prompt.trim())return;if(!$('#ai-loading').hidden){toast('Aguarde a IA Beta terminar a resposta.',true);return}showRight('ai');addAIBubble('user',prompt);$('#ai-input').value='';$('#ai-loading').hidden=false;$('#ai-form button[type="submit"]').disabled=true;try{const context=Object.entries(state.code).map(([k,v])=>`${fileInfo[k].name}:\n${v}`).join('\n\n');const result=await api('/api/ai',{method:'POST',body:{provider:$('#ai-model').value,prompt,code:state.includeCode?context.slice(0,20000):undefined}});$('#ai-loading').hidden=true;await typeAIAnswer(result.text,result.demo);state.aiHistory.push({role:'user',content:prompt},{role:'assistant',content:result.text})}catch(e){showError(e)}finally{$('[data-edit-code]').forEach(el=>el.addEventListener('input',()=>{const snippet=state.aiSnippets.get(el.dataset.editCode);if(snippet)snippet.code=el.textContent}));$('#ai-loading').hidden=true;$('#ai-form button[type="submit"]').disabled=false;$('#ai-scroll').scrollTop=$('#ai-scroll').scrollHeight}}
async function resetAI(){await api('/api/ai/history',{method:'DELETE',body:{}});state.aiHistory=[];state.aiSnippets.clear();$('#ai-messages').innerHTML='';$('#ai-welcome').hidden=false;toast('Memória da conversa apagada.')}
function toggleContext(on=!state.includeCode){state.includeCode=on;$('#ai-context').hidden=!on;toast(on?'O código do Playground será incluído na próxima pergunta.':'Contexto removido.')}
function showError(error){toast(error.message||String(error),true)}
async function showCallSettings(){const devices=await navigator.mediaDevices.enumerateDevices(),mics=devices.filter(d=>d.kind==='audioinput'),cams=devices.filter(d=>d.kind==='videoinput');modal(`${modalHeader('Áudio e vídeo')}<form id="devices-form" class="modal-form"><label class="field">Microfone<select name="mic">${mics.map(d=>`<option value="${esc(d.deviceId)}">${esc(d.label||'Microfone')}</option>`).join('')}</select></label><label class="field">Câmera<select name="camera">${cams.map(d=>`<option value="${esc(d.deviceId)}">${esc(d.label||'Câmera')}</option>`).join('')}</select></label><div class="form-actions"><button class="primary-button">Aplicar</button></div></form>`);wireClose();$('#devices-form').onsubmit=async e=>{e.preventDefault();await calls.setDevices(e.target.mic.value,e.target.camera.value);closeModal();toast('Dispositivos atualizados.')}}

document.addEventListener('click',async e=>{
  const button=e.target.closest('button');if(!button)return;
  try{
    if(button.dataset.server){state.serverId=button.dataset.server;const c=state.data.channels.find(c=>c.server_id===state.serverId&&c.type==='text');await openChannel(c?.id);return}
    if(button.dataset.channel){const c=state.data.channels.find(c=>c.id===button.dataset.channel);return c.type==='voice'?joinCall(c,false):openChannel(c.id)}
    if(button.dataset.direct){await openDirect(button.dataset.direct);return}
    if(button.dataset.friendAccept){await api('/api/friends',{method:'POST',body:{action:'accept',userId:button.dataset.friendAccept}});await refresh();toast('Pessoa adicionada.');return}
    if(button.dataset.friendReject){await api('/api/friends',{method:'POST',body:{action:'reject',userId:button.dataset.friendReject}});await refresh();return}
    if(button.dataset.addUsername!==undefined){showAddFriend(button.dataset.addUsername);return}
    if(button.dataset.reply){setReply(button.dataset.reply);return}
    if(button.dataset.forward){showForward(button.dataset.forward);return}
    if(button.dataset.file){state.file=button.dataset.file;updateEditor();return}
    if(button.dataset.applyCode){const snippet=state.aiSnippets.get(button.dataset.applyCode);if(!snippet||!fileInfo[snippet.language])return;state.code[snippet.language]=snippet.code;state.file=snippet.language;saveLocal();showView('editor');$('#editor-view').classList.add('preview-enabled');$('[data-action="toggle-preview"]').textContent='Ocultar prévia';updateEditor();await validateCode(true);toast(`${fileInfo[snippet.language].name} atualizado pela CodeState AI.`);return}
    if(button.dataset.prompt){await askAI(button.dataset.prompt);return}
    if(button.dataset.react){const updated=await api('/api/reactions',{method:'POST',body:{messageId:button.dataset.message,emoji:button.dataset.react}});const list=state.messages.get(updated.channelId)||[],i=list.findIndex(m=>m.id===updated.id);if(i>=0)list[i]=updated;renderMessages();return}
    if(button.dataset.delete){await api(`/api/messages/${button.dataset.delete}`,{method:'DELETE',body:{}});return}
    const action=button.dataset.action;if(!action)return;
    if(action==='editor'){state.codeChannel=null;showView('editor');updateEditor();closeMobileMenu()}
    else if(action==='welcome'){const c=state.data.channels.find(c=>c.server_id===state.serverId&&c.type==='text');await openChannel(c.id)}
    else if(action==='focus-ai')showRight('ai');else if(action==='members')showRight('members');else if(action==='close-right')$('#right-panel').classList.remove('open');
    else if(action==='toggle-menu')$('#sidebar').classList.toggle('open');else if(action==='save-project')await saveProject();
    else if(action==='refresh-preview')preview();else if(action==='validate-code')await validateCode();else if(action==='toggle-preview'){const editor=$('#editor-view'),enabled=editor.classList.toggle('preview-enabled');button.textContent=enabled?'Ocultar prévia':'Ativar prévia';if(enabled)preview()}else if(action==='desktop-preview'){$('.preview-container').classList.remove('mobile');button.classList.add('active');$('[data-action="mobile-preview"]').classList.remove('active')}
    else if(action==='mobile-preview'){$('.preview-container').classList.add('mobile');button.classList.add('active');$('[data-action="desktop-preview"]').classList.remove('active')}
    else if(action==='download-project'){const blob=new Blob([state.code[state.file]],{type:'text/plain'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=fileInfo[state.file].name;a.click();URL.revokeObjectURL(a.href)}
    else if(action==='review-code'){toggleContext(true);await askAI(`Revise o projeto inteiro, incluindo ${fileInfo[state.file].name}. Aponte erros de sintaxe, melhorias de interface, responsividade, acessibilidade e segurança.`)}
    else if(action==='toggle-context')toggleContext();else if(action==='remove-context')toggleContext(false);else if(action==='reset-ai')await resetAI();
    else if(action==='share-code'){const excerpt=`\`\`\`html\n${state.code.html.slice(0,1800)}\n\`\`\`\n\`\`\`css\n${state.code.css.slice(0,1800)}\n\`\`\``;$('#message-input').value=excerpt;$('#message-input').focus()}
    else if(action==='emoji')showEmoji();else if(action==='attach')$('#file-input').click();else if(action==='search')showSearch();else if(action==='help')showHelp();else if(action==='terms')showTerms();else if(action==='profile')showProfile();else if(action==='server-info')showServerSettings();
    else if(action==='add-friend')showAddFriend();else if(action==='cancel-reply')clearReply();
    else if(action==='invite')await showInvite();else if(action==='roles')await showRoles();else if(action==='new-server')showNewServer();else if(action==='join-server')showJoin();else if(action==='new-channel')showNewChannel('text');else if(action==='new-voice')showNewChannel('voice');else if(action==='new-code')showNewChannel('code');
    else if(action==='integrations')showIntegrations();else if(action==='submit-proposal')showSubmitProposal();else if(action==='review-proposals')showProposals();
    else if(action==='voice'||action==='video'){let c=activeChannel();if(c?.type!=='voice')c=state.data.channels.find(x=>x.server_id===state.serverId&&x.type==='voice');if(c)await joinCall(c,action==='video');else toast('Este servidor ainda não tem canal de voz.',true)}
    else if(action==='toggle-mic'){await calls.toggleMic();callSound('mute')}else if(action==='toggle-camera')await calls.toggleCamera();else if(action==='share-screen'){await calls.shareScreen();callSound('share')}else if(action==='call-settings')await showCallSettings();else if(action==='leave-call'){await calls.leave();const c=state.data.channels.find(x=>x.server_id===state.serverId&&x.type==='text');await openChannel(c.id)}else if(action==='return-call'){showView('call');renderCall()}
  }catch(error){showError(error)}
});
$('#message-form').addEventListener('submit',async e=>{e.preventDefault();const input=$('#message-input'),content=input.value.trim();if(!content)return;input.disabled=true;try{await api(state.dmUserId?'/api/direct-messages':'/api/messages',{method:'POST',body:state.dmUserId?{userId:state.dmUserId,content,replyTo:state.replyTo?.id}:{channelId:state.channelId,content,replyTo:state.replyTo?.id}});input.value='';input.style.height='auto';clearReply()}catch(error){showError(error)}finally{input.disabled=false;input.focus()}});
$('#file-input').addEventListener('change',async e=>{try{await uploadFiles(e.target.files)}catch(error){showError(error);$('#connection-status').innerHTML='<i class="status-dot"></i> Ao vivo'}finally{e.target.value=''}});
$('#call-message-form').addEventListener('submit',async e=>{e.preventDefault();const input=$('#call-message-input'),content=input.value.trim();if(!content)return;await api('/api/messages',{method:'POST',body:{channelId:state.channelId,content}});input.value=''});
let typingTimer=0;$('#message-input').addEventListener('input',e=>{e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,120)+'px';if(!state.dmUserId&&Date.now()>typingTimer){typingTimer=Date.now()+1800;api('/api/typing',{method:'POST',body:{channelId:state.channelId}}).catch(()=>{})}});$('#message-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#message-form').requestSubmit()}});
$('#ai-form').addEventListener('submit',e=>{e.preventDefault();askAI($('#ai-input').value)});$('#ai-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#ai-form').requestSubmit()}});
$('#ai-model').addEventListener('change',e=>{localStorage.setItem('orbit-ai-provider',e.target.value);$('#ai-disclaimer').textContent=e.target.value==='demo'?'IA Beta demonstrativa: respostas simples, aguarde a conclusão.':'IA Beta gratuita: pode demorar e cometer erros. Aguarde a resposta completa.'});
$('#code-input').addEventListener('input',e=>{state.code[state.file]=e.target.value;lineNumbers();preview();$('#save-status').textContent='Alterações não salvas';clearTimeout(state.saveTimer);state.saveTimer=setTimeout(saveLocal,500);clearTimeout(state.validateTimer);state.validateTimer=setTimeout(()=>validateCode(true),900)});$('#code-input').addEventListener('scroll',e=>{$('#line-numbers').scrollTop=e.target.scrollTop});$('#code-input').addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const a=e.target.selectionStart,b=e.target.selectionEnd;e.target.setRangeText('  ',a,b,'end');e.target.dispatchEvent(new Event('input'))}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showSearch()}if(e.key==='Escape'){$('#right-panel').classList.remove('open');closeMobileMenu()}});window.addEventListener('beforeunload',()=>{state.events?.close();calls.localStream?.getTracks().forEach(t=>t.stop())});
function closeMobileMenu(){if(innerWidth<=760)$('#sidebar').classList.remove('open')}
function modalHeader(title){return `<div class="modal-header"><h2>${esc(title)}</h2><button class="icon-button" data-close aria-label="Fechar">${icon('close')}</button></div>`}
function wireClose(){$$('[data-close]',$('#modal')).forEach(b=>b.onclick=closeModal)}
function showEmoji(){modal(`${modalHeader('Uma reação vale mil palavras')}<p class="modal-description">Escolha um emoji para colocar na sua mensagem.</p><div class="emoji-grid">${['✨','🔥','💡','❤️','👍','🚀'].map(x=>`<button data-emoji="${x}">${x}</button>`).join('')}</div>`);wireClose();$$('[data-emoji]',$('#modal')).forEach(b=>b.onclick=()=>{const input=$('#message-input');input.value+=b.dataset.emoji;closeModal();input.focus()})}
function showAddFriend(username=''){modal(`${modalHeader('Adicionar uma pessoa')}<p class="modal-description">Digite o username exato. A conversa privada será liberada quando a pessoa aceitar.</p><form id="friend-form" class="modal-form"><label class="field">Username<input name="username" minlength="3" maxlength="32" pattern="[a-zA-Z0-9_-]+" value="${esc(username)}" placeholder="username" required></label><div class="form-error"></div><div class="form-actions"><button class="primary-button">Enviar pedido</button></div></form>`);wireClose();$('#friend-form').onsubmit=async event=>{event.preventDefault();try{await api('/api/friends',{method:'POST',body:{action:'request',username:event.target.username.value.trim()}});closeModal();await refresh();toast('Pedido de amizade enviado.')}catch(error){$('.form-error',$('#modal')).textContent=error.message}}}
function showForward(messageId){const message=(state.messages.get(currentMessageKey())||[]).find(item=>item.id===messageId);if(!message)return;const channels=state.data.channels.filter(channel=>['text','voice'].includes(channel.type)&&!channel.read_only),friends=state.data.friends||[],endpoint=message.direct?'/api/direct-messages/forward':'/api/messages/forward';modal(`${modalHeader('Encaminhar mensagem')}<p class="modal-description">Escolha um canal ou uma conversa privada.</p><div class="forward-targets">${friends.map(user=>`<button class="forward-target" data-forward-user="${esc(user.id)}">${icon('messageCircle',15)}<span>${esc(user.name)}</span><small>Privado</small></button>`).join('')}${channels.map(channel=>{const server=state.data.servers.find(item=>item.id===channel.server_id);return `<button class="forward-target" data-forward-channel="${esc(channel.id)}">${icon('hash',15)}<span>${esc(channel.name)}</span><small>${esc(server?.name||'Servidor')}</small></button>`}).join('')||'<p class="no-results">Nenhum destino disponível.</p>'}</div>`);wireClose();$$('[data-forward-user],[data-forward-channel]',$('#modal')).forEach(button=>button.onclick=async()=>{try{await api(endpoint,{method:'POST',body:{messageId,userId:button.dataset.forwardUser,channelId:button.dataset.forwardChannel}});closeModal();toast('Mensagem encaminhada.')}catch(error){showError(error)}})}
function showHelp(){modal(`${modalHeader('Bem-vindo ao CodeState Beta')}<p class="modal-description">Seu espaço para conversar, testar ideias e construir em boa companhia.</p><div class="help-list"><div class="help-row">${icon('hash')}<div><strong>Chat em tempo real</strong><p>Crie um servidor para conversar, enviar arquivos e ver presença ao vivo. O canal de apresentação é somente leitura.</p></div></div><div class="help-row">${icon('code')}<div><strong>Playground seguro</strong><p>Edite sete linguagens, verifique a sintaxe e ative a prévia quando quiser.</p></div></div><div class="help-row">${icon('video')}<div><strong>Chamadas e tela</strong><p>Entre em um canal de voz para usar áudio, câmera, chat da chamada ou compartilhar sua tela via WebRTC.</p></div></div><div class="help-row">${icon('sparkles')}<div><strong>IA em versão Beta</strong><p>Os modelos gratuitos não são avançados e podem demorar. Aguarde cada resposta terminar.</p></div></div></div><button class="secondary-button full-width" data-action="terms">Ler Termos e Regras</button>`);wireClose()}
function showTerms(){modal(`${modalHeader('Termos e Regras')}<div class="legal-copy"><p><strong>Versão Beta · vigente desde 8 de setembro de 2026</strong></p><h3>Convivência</h3><p>Respeite outras pessoas. Não publique assédio, ameaças, fraude, spam, conteúdo ilegal ou material que viole direitos de terceiros.</p><h3>Conta e conteúdo</h3><p>Você é responsável pelo que envia, pelos seus arquivos e pela segurança da sua senha. Não compartilhe malware, credenciais ou dados privados sem autorização.</p><h3>Mensagens privadas</h3><p>Conversas privadas ficam visíveis aos dois participantes e são armazenadas no servidor; elas não usam criptografia de ponta a ponta.</p><h3>Chamadas</h3><p>Voz e câmera usam WebRTC. Se a tela direta não conectar entre redes, quadros comprimidos podem passar temporariamente pelo servidor HTTPS apenas para participantes do mesmo canal de voz; eles não são armazenados. Ative esses recursos com consentimento e não grave nem redistribua uma chamada sem permissão.</p><h3>IA Beta</h3><p>A IA pode demorar, errar ou produzir código inseguro. Ela não é um modelo avançado. Revise e teste qualquer resposta antes de usar ou compilar.</p><h3>Disponibilidade e moderação</h3><p>O serviço está em testes, pode mudar ou ficar indisponível. Conteúdo e contas que violem estas regras podem ser limitados ou removidos.</p><p><a href="/terms.html" target="_blank" rel="noopener">Abrir a versão completa</a></p></div>`);wireClose()}
async function imageData(input,current,remove){if(remove)return'';const file=input.files?.[0];if(!file)return current||'';if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)||file.size>1500000)throw new Error('Use PNG, JPG, WebP ou GIF com até 1,5 MB.');return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Não foi possível ler a imagem.'));reader.readAsDataURL(file)})}
function showCredentials(credentials=savedCredentials(),created=false){if(!credentials){toast('As credenciais não estão salvas neste dispositivo.',true);return}modal(`${modalHeader(created?'Sua conta está pronta':'Credenciais salvas')}<p class="modal-description">${created?'Guarde estes dados para entrar no site ou no aplicativo em outro dispositivo.':'Estas credenciais ficam somente neste dispositivo e permitem reconectar automaticamente.'}</p><div class="credentials-card"><label>Usuário<code>${esc(credentials.username)}</code></label><label>Senha<div><input id="saved-password" type="password" readonly value="${esc(credentials.password)}"><button class="icon-button" id="reveal-password" aria-label="Mostrar senha">${icon('eye')}</button></div></label></div><div class="form-actions"><button class="secondary-button" id="copy-credentials">${icon('copy')} Copiar</button><button class="primary-button" data-close>Entendi</button></div>`);wireClose();$('#reveal-password').onclick=()=>{const input=$('#saved-password');input.type=input.type==='password'?'text':'password'};$('#copy-credentials').onclick=async()=>{await navigator.clipboard.writeText(`CodeState\nUsuário: ${credentials.username}\nSenha: ${credentials.password}`);toast('Credenciais copiadas.')}}
function showProfile(){const u=state.data.user,saved=savedCredentials();modal(`${modalHeader('Editar perfil')}<div class="profile-editor-banner">${u.banner?`<img src="${esc(u.banner)}" alt="Banner atual">`:'Seu banner aparecerá aqui'}</div><div class="profile-editor-card">${avatarHTML(u)}<strong>${esc(u.name)}</strong></div><form id="profile-form" class="modal-form"><label class="field">Nome exibido<input name="name" minlength="2" maxlength="40" value="${esc(u.name)}" required><small>É o nome que as outras pessoas verão.</small></label><label class="field">Username<input name="username" minlength="3" maxlength="32" pattern="[a-zA-Z0-9_-]+" value="${esc(u.username||'')}" autocomplete="username" required><small>Único; use letras sem acento, números, _ ou -.</small></label><div class="image-fields"><label class="field">Foto de perfil<input name="avatar" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><span class="remove-image"><input name="removeAvatar" type="checkbox"> Remover foto</span></label><label class="field">Banner do perfil<input name="banner" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><span class="remove-image"><input name="removeBanner" type="checkbox"> Remover banner</span></label></div><p class="modal-description">PNG, JPG, WebP ou GIF animado, até 1,5 MB por imagem.</p><div class="form-error"></div><div class="form-actions"><button type="button" class="text-button" id="logout">Sair deste dispositivo</button><button class="primary-button">Salvar perfil</button></div></form>${saved?'<hr class="profile-divider"><button id="show-credentials" class="secondary-button full-width">Ver credenciais salvas</button>':''}`);wireClose();$('#profile-form').onsubmit=async e=>{e.preventDefault();try{const oldUsername=u.username,avatar=await imageData(e.target.avatar,u.avatar,e.target.removeAvatar.checked),banner=await imageData(e.target.banner,u.banner,e.target.removeBanner.checked);const u2=await api('/api/profile',{method:'PATCH',body:{name:e.target.name.value,username:e.target.username.value,avatar,banner}});if(saved&&saved.username===oldUsername)saveCredentials({...saved,username:u2.username,name:u2.name});state.data.user=u2;state.data.members=state.data.members.map(member=>member.id===u2.id?{...member,...u2}:member);renderShell();renderMembers();closeModal();toast('Perfil e username atualizados.')}catch(x){$('.form-error',$('#modal')).textContent=x.message}};$('#logout').onclick=async()=>{forgetCredentials();await api('/api/logout',{method:'POST',body:{}});location.reload()};if($('#show-credentials'))$('#show-credentials').onclick=()=>showCredentials()}
function showRegister(){modal(`${modalHeader('Crie sua conta')}<p class="modal-description">Mantenha seu nome, seus projetos e crie servidores privados.</p><form id="register-form" class="modal-form"><label class="field">Nome<input name="name" minlength="2" maxlength="40" value="${esc(state.data.user.name)}" required></label><label class="field">Usuário<input name="username" minlength="3" maxlength="32" pattern="[a-zA-Z0-9_-]+" autocomplete="username" required><small>Letras, números, _ ou -.</small></label><label class="field">Senha<input name="password" type="password" minlength="10" maxlength="128" autocomplete="new-password" required><small>Maiúscula, minúscula, número e símbolo; sem repetições longas.</small></label><label class="terms-check"><input name="terms" type="checkbox" required><span>Li e aceito os <a href="/terms.html" target="_blank" rel="noopener">Termos e Regras</a>.</span></label><div class="form-error"></div><div class="form-actions"><button class="primary-button">Criar conta</button></div></form>`);wireClose();$('#register-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('/api/register',{method:'POST',body:Object.fromEntries(f)});location.reload()}catch(x){$('.form-error',$('#modal')).textContent=x.message}}}
async function showInvite(){try{const d=await api(`/api/invite?serverId=${encodeURIComponent(state.serverId)}`);if(!d.invite){toast('O servidor público CodeState não precisa de convite.');return}const value=d.url||d.invite;modal(`${modalHeader('Convide seu time')}<p class="modal-description">${d.url?'Este link usa o endereço público seguro do CodeState.':'O endereço público ainda não foi configurado. Compartilhe este código somente com pessoas conectadas ao mesmo servidor CodeState.'}</p><div class="invite-url">${esc(value)}</div><button id="copy-invite" class="primary-button full-width">${icon('copy')} Copiar ${d.url?'link':'código'}</button>`);wireClose();$('#copy-invite').onclick=async()=>{await navigator.clipboard.writeText(value);toast(d.url?'Link copiado.':'Código copiado.');closeModal()}}catch(e){showError(e)}}
function showNewServer(){if(state.data.user.guest){showRegister();return}modal(`${modalHeader('Crie um novo espaço')}<p class="modal-description">Um servidor privado para seu time, projeto ou comunidade.</p><form id="server-form" class="modal-form"><label class="field">Nome do servidor<input name="name" minlength="2" maxlength="40" placeholder="Ex.: Estúdio Aurora" required></label><label class="field">Descrição<textarea name="description" maxlength="150" placeholder="O que vocês vão criar juntos?"></textarea></label><label class="field">Fonte do servidor<select name="font">${fontOptions('inter')}</select></label><label class="field">Foto do servidor<input name="icon" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><small>PNG, JPG, WebP ou GIF, até 1,5 MB.</small></label><div class="form-error"></div><div class="form-actions"><button class="primary-button">Criar servidor</button></div></form>`);wireClose();$('#server-form').onsubmit=async e=>{e.preventDefault();try{const icon=await imageData(e.target.icon,'',false),d=await api('/api/servers',{method:'POST',body:{name:e.target.name.value,description:e.target.description.value,font:e.target.font.value,icon}});closeModal();await refresh();state.serverId=d.id;renderShell();const c=state.data.channels.find(c=>c.server_id===d.id&&c.type==='text');await openChannel(c.id);toast('Servidor criado com cargos Dono e Membro.')}catch(x){$('.form-error',$('#modal')).textContent=x.message}}}
function showServerSettings(){const s=activeServer(),editable=s.ownerId===state.data.user.id||s.permissions?.some(permission=>['administrator','manage_server'].includes(permission));if(!editable){modal(`${modalHeader(s.name)}<p class="modal-description">${esc(s.description)}</p><button class="primary-button full-width" id="server-invite">Convidar pessoas</button>`);wireClose();$('#server-invite').onclick=()=>{closeModal();showInvite()};return}modal(`${modalHeader('Personalizar servidor')}<form id="server-settings-form" class="modal-form"><label class="field">Nome<input name="name" minlength="2" maxlength="40" value="${esc(s.name)}" required></label><label class="field">Descrição<textarea name="description" maxlength="150">${esc(s.description)}</textarea></label><label class="field">Fonte<select name="font">${fontOptions(s.font)}</select></label><label class="field">Nova foto<input name="icon" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><span class="remove-image"><input name="removeIcon" type="checkbox"> Remover foto</span></label><div class="form-error"></div><div class="form-actions"><button type="button" class="secondary-button" id="open-roles">Cargos</button><button class="primary-button">Salvar servidor</button></div></form>`);wireClose();$('#open-roles').onclick=()=>{closeModal();showRoles()};$('#server-settings-form').onsubmit=async e=>{e.preventDefault();try{const icon=await imageData(e.target.icon,s.icon,e.target.removeIcon.checked);await api(`/api/servers/${encodeURIComponent(s.id)}`,{method:'PATCH',body:{name:e.target.name.value,description:e.target.description.value,font:e.target.font.value,icon}});closeModal();await refresh();toast('Servidor atualizado.')}catch(error){$('.form-error',$('#modal')).textContent=error.message}}}
function showJoin(){modal(`${modalHeader('Entrar em um servidor')}<p class="modal-description">Cole o código ou link de convite que você recebeu.</p><form id="join-form" class="modal-form"><label class="field">Convite<input name="invite" minlength="20" maxlength="300" required></label><div class="form-error"></div><div class="form-actions"><button class="primary-button">Entrar</button></div></form>`);wireClose();$('#join-form').onsubmit=async e=>{e.preventDefault();let value=e.target.invite.value.trim();try{if(value.includes('?'))value=new URL(value).searchParams.get('invite')||value;const d=await api('/api/join',{method:'POST',body:{invite:value}});closeModal();await refresh();state.serverId=d.id;renderShell();const c=state.data.channels.find(c=>c.server_id===d.id&&c.type==='text');await openChannel(c.id)}catch(x){$('.form-error',$('#modal')).textContent=x.message}}}
function showNewChannel(type){const s=activeServer();if(s.ownerId!==state.data.user.id&&!s.permissions?.some(permission=>['administrator','manage_channels'].includes(permission))){toast('Você precisa do cargo com permissão para criar canais.',true);return}const label=type==='text'?'texto':type==='code'?'código':'voz';modal(`${modalHeader(`Novo canal de ${label}`)}<form id="channel-form" class="modal-form"><label class="field">Nome<input name="name" minlength="2" maxlength="30" placeholder="${type==='code'?'projeto-api':type==='text'?'novidades':'Sala de criação'}" required></label><label class="field">Fonte do canal<select name="font">${fontOptions('inherit',true)}</select></label><label class="toggle-field"><input name="vfx" type="checkbox"><span></span><strong>VFX ao redor do canal</strong></label><p class="modal-description">O efeito destaca o canal com um brilho animado discreto.</p><div class="form-error"></div><div class="form-actions"><button class="primary-button">Criar canal</button></div></form>`);wireClose();$('#channel-form').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/channels',{method:'POST',body:{serverId:state.serverId,name:e.target.name.value,type,font:e.target.font.value,vfx:e.target.vfx.checked}});closeModal();await refresh();const c=state.data.channels.find(c=>c.id===d.id);type==='voice'?toast('Canal de voz criado.'):await openChannel(c.id)}catch(x){$('.form-error',$('#modal')).textContent=x.message}}}
async function showRoles(){const s=activeServer();try{const data=await api(`/api/roles?serverId=${encodeURIComponent(s.id)}`);if(!data.canManage){toast('Você não pode gerenciar cargos.',true);return}const members=state.data.members.filter(member=>member.serverId===s.id&&!member.bot);modal(`${modalHeader('Cargos do servidor')}<form id="role-form" class="modal-form"><div class="role-create-row"><label class="field">Nome<input name="name" minlength="2" maxlength="30" placeholder="Moderador" required></label><label class="field">Cor<input name="color" type="color" value="#b8b8ff"></label></div><div class="permission-grid"><label><input type="checkbox" name="manage_channels"> Criar canais</label><label><input type="checkbox" name="manage_server"> Editar servidor</label><label><input type="checkbox" name="manage_messages"> Moderar mensagens</label><label><input type="checkbox" name="invite_members"> Convidar membros</label></div><button class="primary-button full-width">Criar cargo</button></form><div class="role-list">${data.roles.map(role=>`<section><header><i style="background:${role.color}"></i><strong>${esc(role.name)}</strong></header>${role.id.endsWith(':owner')?'':members.map(member=>`<label><input type="checkbox" data-role="${esc(role.id)}" data-user="${esc(member.id)}" ${role.memberIds.includes(member.id)?'checked':''}> ${esc(member.name)}</label>`).join('')}</section>`).join('')}</div><div class="form-error"></div>`);wireClose();$('#role-form').onsubmit=async e=>{e.preventDefault();try{const permissions=['manage_channels','manage_server','manage_messages','invite_members'].filter(key=>e.target[key].checked);await api('/api/roles',{method:'POST',body:{action:'create',serverId:s.id,name:e.target.name.value,color:e.target.color.value,permissions}});closeModal();await showRoles()}catch(error){$('.form-error',$('#modal')).textContent=error.message}};$$('[data-role]',$('#modal')).forEach(input=>input.onchange=async()=>{try{await api('/api/roles',{method:'POST',body:{action:'assign',serverId:s.id,roleId:input.dataset.role,userId:input.dataset.user,enabled:input.checked}});toast('Cargo atualizado.')}catch(error){input.checked=!input.checked;showError(error)}})}catch(error){showError(error)}}
function showIntegrations(){modal(`${modalHeader('Skills, Agents e MCPs')}<p class="modal-description">Organize instruções, agentes especializados e servidores MCP usados pela CodeState AI.</p><div class="integration-grid"><section><strong>Skills</strong><p>Pacotes de instruções para revisão, testes, UI e documentação.</p><button class="secondary-button" data-copy-prompt="Use a skill de revisão de código neste projeto.">Usar no prompt</button></section><section><strong>Agents</strong><p>Divida uma tarefa entre agentes de frontend, backend e segurança.</p><button class="secondary-button" data-copy-prompt="Crie agentes para frontend, backend e segurança e coordene a solução.">Usar no prompt</button></section><section><strong>MCPs</strong><p>Conecte ferramentas MCP no servidor que hospeda o CodeState; segredos ficam fora do navegador.</p><button class="secondary-button" data-copy-prompt="Liste os MCPs disponíveis e use o mais adequado para esta tarefa.">Usar no prompt</button></section></div>`);wireClose();$$('[data-copy-prompt]',$('#modal')).forEach(b=>b.onclick=()=>{closeModal();showRight('ai');$('#ai-input').value=b.dataset.copyPrompt;$('#ai-input').focus()})}
function showSubmitProposal(){if(!state.codeChannel)return;modal(`${modalHeader('Propor alteração')}<p class="modal-description">O dono do servidor precisa aceitar antes que este código vire a versão compartilhada.</p><form id="proposal-form" class="modal-form"><label class="field">Arquivo<input value="${esc(fileInfo[state.file].name)}" disabled></label><label class="field">Resumo<textarea name="note" maxlength="300" placeholder="O que esta alteração resolve?"></textarea></label><div class="form-error"></div><div class="form-actions"><button class="primary-button">Enviar para revisão</button></div></form>`);wireClose();$('#proposal-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/code-proposals',{method:'POST',body:{channelId:state.channelId,language:state.file,content:state.code[state.file],note:e.target.note.value}});closeModal();toast('Proposta enviada ao dono.')}catch(x){$('.form-error',$('#modal')).textContent=x.message}}}
function showProposals(){if(!state.codeChannel?.owner)return;const items=state.codeChannel.proposals;modal(`${modalHeader('Revisar propostas')}<div class="proposal-list">${items.length?items.map(p=>`<article><header><strong>${esc(fileInfo[p.language]?.name||p.language)}</strong><span class="proposal-status ${p.status}">${esc(p.status)}</span></header><small>${esc(p.userName)} · ${new Date(p.createdAt).toLocaleString('pt-BR')}</small><p>${esc(p.note||'Sem resumo.')}</p><details><summary>Ver código</summary><pre><code>${esc(p.content)}</code></pre></details>${p.status==='pending'?`<div><button class="secondary-button" data-proposal="${p.id}" data-decision="rejected">Recusar</button><button class="primary-button" data-proposal="${p.id}" data-decision="accepted">Aceitar</button></div>`:''}</article>`).join(''):'<p class="no-results">Nenhuma proposta ainda.</p>'}</div>`);wireClose();$$('[data-proposal]',$('#modal')).forEach(b=>b.onclick=async()=>{await api(`/api/code-proposals/${b.dataset.proposal}`,{method:'PATCH',body:{status:b.dataset.decision}});closeModal();await openCodeChannel(state.codeChannel.channel);toast(b.dataset.decision==='accepted'?'Alteração aceita.':'Alteração recusada.')})}
function showSearch(){modal(`${modalHeader('Buscar mensagens')}<input id="search-input" class="search-input" placeholder="Digite pelo menos 2 caracteres" autofocus><div id="search-results" class="search-results"><p class="no-results">A busca acontece nas mensagens já carregadas desta conversa.</p></div>`);wireClose();$('#search-input').oninput=e=>{const q=e.target.value.trim().toLowerCase(),list=state.messages.get(currentMessageKey())||[];const found=q.length<2?[]:list.filter(m=>m.content.toLowerCase().includes(q)).slice(-20);$('#search-results').innerHTML=found.length?found.map(m=>`<button class="search-result" data-jump="${m.id}"><strong>${esc(m.user.name)} · ${formatTime(m.createdAt)}</strong><p>${esc(m.content.slice(0,220))}</p></button>`).join(''):'<p class="no-results">Nenhuma mensagem encontrada.</p>';$$('[data-jump]',$('#modal')).forEach(b=>b.onclick=()=>{closeModal();const el=$(`#msg-${b.dataset.jump}`);el?.scrollIntoView({behavior:'smooth',block:'center'});el?.classList.add('highlight-message');setTimeout(()=>el?.classList.remove('highlight-message'),2100)})}}

const invite=new URLSearchParams(location.search).get('invite');if(invite){history.replaceState({},'',location.pathname);boot().then(async()=>{try{const d=await api('/api/join',{method:'POST',body:{invite}});await refresh();state.serverId=d.id;const c=state.data.channels.find(c=>c.server_id===d.id&&c.type==='text');await openChannel(c.id);toast('Você entrou no servidor.')}catch(e){showError(e)}}).catch(showError)}else boot().catch(e=>{$('#boot p').textContent='Não foi possível iniciar. Atualize a página.';showError(e)});
